-- V90: fictional demo data for SpareSlot (infra range V90+). Every name, organisation, place and email is
-- invented; emails use the reserved .example domain. Nothing here is a real person or institution.
--
-- All demo accounts share one password, set here as a BCrypt hash (strength 10) and never written in the
-- README of a deployed app. Judges use the "Sign in as" panel (DEMO_LOGIN_ENABLED=true) instead.
--
-- Times are relative to the moment this migration runs, so "upcoming", "active" and "overdue" hold at deploy
-- time. Bookings are written in their real order (request, approval with the deposit snapshot, ledger rows,
-- condition records, status changes), so every V1-V3 trigger checks this data as it goes in, and each step
-- writes the audit event a real action would.

-- ---------------------------------------------------------------- helpers (session-only, dropped at the end)

CREATE FUNCTION pg_temp.t(p_days numeric, p_hour numeric) RETURNS timestamptz LANGUAGE sql AS $$
    SELECT (date_trunc('day', now() AT TIME ZONE 'Asia/Kolkata')
            + make_interval(secs => ((p_days * 24 + p_hour) * 3600)::double precision)) AT TIME ZONE 'Asia/Kolkata'
$$;

CREATE FUNCTION pg_temp.ev(p_at timestamptz, p_actor uuid, p_role text, p_action text, p_type text, p_id uuid,
                           p_from text, p_to text, p_reason text, p_details jsonb DEFAULT '{}'::jsonb)
RETURNS void LANGUAGE sql AS $$
    INSERT INTO audit_events (at, actor_id, actor_role, action, entity_type, entity_id, from_status, to_status, reason, details)
    VALUES (p_at, p_actor, p_role, p_action, p_type, p_id, p_from, p_to, p_reason, p_details)
$$;

CREATE FUNCTION pg_temp.note(p_user uuid, p_msg text, p_booking uuid, p_at timestamptz, p_read boolean)
RETURNS void LANGUAGE sql AS $$
    INSERT INTO notifications (user_id, message, entity_type, entity_id, created_at, read_at)
    VALUES (p_user, p_msg, 'booking', p_booking, p_at, CASE WHEN p_read THEN p_at + interval '10 minutes' END)
$$;

CREATE FUNCTION pg_temp.request(p_id uuid, p_res uuid, p_user uuid, p_start timestamptz, p_end timestamptz,
                                p_purpose text, p_at timestamptz) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO bookings (id, resource_id, requester_id, team_id, start_at, end_at, purpose, created_at, updated_at)
    VALUES (p_id, p_res, p_user, (SELECT team_id FROM users WHERE id = p_user), p_start, p_end, p_purpose, p_at, p_at);
    PERFORM pg_temp.ev(p_at, p_user, 'user', 'booking.requested', 'booking', p_id, NULL, 'requested', NULL,
                       jsonb_build_object('resourceId', p_res, 'purpose', p_purpose));
END $$;

-- one edge of booking_transitions, as BookingService.transition does it (p_actor NULL = the system)
CREATE FUNCTION pg_temp.move(p_id uuid, p_to text, p_actor uuid, p_role text, p_reason text, p_at timestamptz)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE
    old_status text;
    dep        integer;
    rule       booking_transitions%ROWTYPE;
BEGIN
    SELECT b.status, r.deposit_minor INTO old_status, dep
    FROM bookings b JOIN resources r ON r.id = b.resource_id WHERE b.id = p_id;
    SELECT * INTO rule FROM booking_transitions WHERE from_status = old_status AND to_status = p_to;
    UPDATE bookings SET
        status          = p_to,
        decision_reason = CASE WHEN rule.requires_reason THEN p_reason ELSE decision_reason END,
        decided_by      = CASE WHEN rule.requires_reason THEN p_actor ELSE decided_by END,
        checked_in_at   = CASE WHEN p_to = 'checked_in' THEN p_at ELSE checked_in_at END,
        returned_at     = CASE WHEN p_to = 'returned' THEN p_at ELSE returned_at END,
        closed_at       = CASE WHEN p_to = 'closed' THEN p_at ELSE closed_at END,
        deposit_minor   = CASE WHEN p_to = 'approved' AND deposit_status = 'none' AND dep > 0 THEN dep ELSE deposit_minor END,
        deposit_status  = CASE WHEN p_to = 'approved' AND deposit_status = 'none' AND dep > 0 THEN 'pending' ELSE deposit_status END
    WHERE id = p_id;
    IF rule.requires_reason THEN
        UPDATE bookings SET decided_at = p_at WHERE id = p_id;
    END IF;
    PERFORM pg_temp.ev(p_at, p_actor, p_role, 'booking.' || p_to, 'booking', p_id, old_status, p_to, p_reason);
END $$;

CREATE FUNCTION pg_temp.cond(p_booking uuid, p_phase text, p_rating text, p_notes text, p_by uuid, p_at timestamptz)
RETURNS void LANGUAGE sql AS $$
    INSERT INTO condition_records (booking_id, phase, rating, notes, recorded_by, recorded_at)
    VALUES (p_booking, p_phase, p_rating, p_notes, p_by, p_at)
$$;

-- a ledger row (the trigger moves bookings.deposit_status) and its audit event, as DepositService does it
CREATE FUNCTION pg_temp.ledger(p_booking uuid, p_kind text, p_provider text, p_ref text, p_actor uuid, p_role text,
                               p_reason text, p_at timestamptz) RETURNS void LANGUAGE plpgsql AS $$
DECLARE
    old_status text;
    amount     integer;
BEGIN
    SELECT deposit_status, deposit_minor INTO old_status, amount FROM bookings WHERE id = p_booking;
    INSERT INTO deposit_transactions (booking_id, kind, amount_minor, provider, provider_ref, actor_id, reason, created_at)
    VALUES (p_booking, p_kind, amount, p_provider, p_ref, p_actor, p_reason, p_at);
    PERFORM pg_temp.ev(p_at, CASE WHEN p_role = 'system' THEN NULL ELSE p_actor END, p_role,
                       'deposit.' || CASE p_kind WHEN 'charge' THEN 'charged' WHEN 'refund' THEN 'refunded'
                                                 WHEN 'forfeit' THEN 'forfeited' ELSE 'waived' END,
                       'booking', p_booking, old_status, (SELECT deposit_status FROM bookings WHERE id = p_booking),
                       p_reason, jsonb_build_object('amountMinor', amount, 'currency', 'INR', 'provider', p_provider,
                                                    'providerRef', p_ref));
END $$;

CREATE FUNCTION pg_temp.photo(p_id uuid, p_booking uuid, p_phase text, p_side text, p_blob uuid, p_caption text,
                              p_by uuid, p_role text, p_at timestamptz) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO booking_photos (id, booking_id, phase, side, blob_id, caption, uploaded_by, created_at)
    VALUES (p_id, p_booking, p_phase, p_side, p_blob, p_caption, p_by, p_at);
    PERFORM pg_temp.ev(p_at, p_by, p_role, 'photo.added', 'booking', p_booking, NULL, NULL, p_caption,
                       jsonb_build_object('photoId', p_id, 'phase', p_phase, 'side', p_side));
END $$;

