                  jsonb_build_object('kind', c.kind))
FROM credentials c WHERE c.id::text LIKE '70000000-%';
SELECT pg_temp.ev(c.reviewed_at, c.reviewed_by, u.role, 'credential.' || c.status, 'credential', c.id, 'pending', c.status,
                  c.review_reason, jsonb_build_object('kind', c.kind, 'userId', c.user_id))
FROM credentials c JOIN users u ON u.id = c.reviewed_by WHERE c.status <> 'pending' AND c.id::text LIKE '70000000-%';

